(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-421":{scenario:{company:"Sóng Bạc Media",supervisor:{name:"Lý Quốc Trung",role:{vi:"Trưởng bộ phận Hậu kỳ",en:"Post-production Supervisor"}},ref_code:"TVC-0530",title:{vi:"Đúng tốc độ khung hình. Đúng độ lớn âm thanh. Đúng bản quyền.",en:"Right frame rate. Right loudness. Right licence."},brief:{vi:"Bạn hoàn thiện TVC 30 giây TVC-0530 để giao kênh truyền hình. Toàn bộ cảnh quay ở 25 fps nhưng bản dựng nháp đặt timeline 29.97 fps. Đặc tả của kênh (mô phỏng theo EBU R128): độ lớn tích hợp -23 LUFS, đỉnh thật tối đa -1 dBTP; bản mix hiện đo được -11 LUFS. Đối chiếu bảng thông số xuất nháp với đặc tả đã duyệt, sửa tốc độ khung hình và mức hiệu chỉnh độ lớn cần áp, rồi lập báo cáo có căn cứ.",en:"You are finishing 30-second spot TVC-0530 for delivery to a TV channel. All footage was shot at 25 fps but the draft edit uses a 29.97 fps timeline. The channel spec (modelled on EBU R128): integrated loudness -23 LUFS, true peak no higher than -1 dBTP; the current mix measures -11 LUFS. Compare the draft export sheet with the approved spec, correct the frame rate and the loudness gain to apply, then write an evidence-based report."},reference_title:{vi:"Đặc tả phát sóng & phiếu đo âm thanh đã duyệt · TVC-0530",en:"Approved broadcast spec & loudness sheet · TVC-0530"},fields:[{id:"FRAME_RATE",label:{vi:"Tốc độ khung hình timeline và file xuất (fps)",en:"Timeline and export frame rate (fps)"},initial:"29.97",expected:"25",choices:["23.976","25","29.97"],reference:"Đặc tả kỹ thuật phát sóng của kênh",hint:{vi:"Giữ đúng tốc độ khung hình gốc và đặc tả kênh vùng 50 Hz; chuyển 25 sang 29.97 gây giật hình, lệch timecode.",en:"Keep the native frame rate and the 50 Hz channel spec; converting 25 to 29.97 causes judder and timecode drift."}},{id:"GAIN_DB",label:{vi:"Mức hiệu chỉnh độ lớn cần áp (dB)",en:"Loudness gain to apply (dB)"},initial:"-3",expected:"-12",reference:"Phiếu đo độ lớn âm thanh",ref_value:{vi:"Bản mix đo -11 LUFS tích hợp; mục tiêu của kênh -23 LUFS",en:"Mix measures -11 LUFS integrated; channel target -23 LUFS"},hint:{vi:"Bản nháp dùng preset mạng xã hội -14 LUFS; bản phát sóng phải theo mục tiêu của kênh.",en:"The draft used a -14 LUFS social media preset; the broadcast master must follow the channel target."}}],sop32:{vi:"Mức hiệu chỉnh (dB) = độ lớn mục tiêu - độ lớn đo được (LUFS); giá trị âm là giảm. Sau hiệu chỉnh phải đo lại để độ lớn đạt mục tiêu và đỉnh thật không vượt -1 dBTP.",en:"Gain (dB) = target loudness - measured loudness (LUFS); a negative value means reduce. After applying it, re-measure so loudness hits the target and true peak stays at or below -1 dBTP."},context:{label:"BẢNG THÔNG SỐ XUẤT / TVC-0530",metrics:[{label:{vi:"Thời lượng",en:"Duration"},value:"30 s"},{label:{vi:"Độ lớn đo được",en:"Measured loudness"},value:"-11 LUFS"},{label:{vi:"Mục tiêu của kênh",en:"Channel target"},value:"-23 LUFS / -1 dBTP"}]},crisis:{vi:"Khách hàng nhắn: “Chèn bài hit đang thịnh hành làm nhạc nền đi, phát vài tuần thôi ai mà kiểm tra. Mua bản quyền thì không kịp lên sóng thứ Hai.”",en:"The client messages you: “Drop in that trending hit as the soundtrack, it only airs for a few weeks so nobody will check. Licensing it would miss Monday's air date.”"},options:{safe:{vi:"Không dùng nhạc chưa có giấy phép; báo Producer và khách bằng văn bản về rủi ro, đề xuất nhạc thư viện có giấy phép phát sóng hoặc nhạc sáng tác riêng và cập nhật lịch giao file.",en:"Use no unlicensed music; inform the producer and the client in writing about the risk, propose broadcast-licensed library music or an original score, and update the delivery schedule."},shortcut:{vi:"Chèn bài hit vào cho kịp lên sóng, nếu bị khiếu nại thì thay nhạc sau.",en:"Use the hit to make the air date and swap the music later if there is a claim."},wait:{vi:"Dừng dựng và chờ khách tự lo chuyện bản quyền nhạc.",en:"Stop editing and wait for the client to sort out the music rights."}},questions:{vi:["Vì sao phải dựng và xuất ở 25 fps, áp -12 dB thay vì -3 dB? Bạn kiểm chứng kết quả bằng chỉ số nào?","Dùng nhạc chưa có giấy phép trong TVC gây rủi ro gì cho khách, kênh và công ty? Bạn xử lý yêu cầu này ra sao?"],en:["Why must you edit and export at 25 fps and apply -12 dB instead of -3 dB? Which readings prove the result?","What risks does unlicensed music in a TV spot create for the client, the channel and the agency? How do you handle the request?"]},hints:{vi:["So cài đặt timeline nháp với đặc tả kênh và tốc độ khung hình của cảnh quay gốc.","Lấy độ lớn mục tiêu trừ độ lớn đo được theo SOP mục 3.2 và chú ý dấu âm.","Đọc lại SOP mục 4.2: âm nhạc, cảnh quay, hình ảnh đều phải có giấy phép phù hợp mục đích phát sóng."],en:["Compare the draft timeline settings with the channel spec and the native frame rate of the footage.","Subtract the measured loudness from the target as in SOP 3.2 and watch the sign.","Re-read SOP 4.2: music, footage and images all need licences that cover broadcast use."]}},learning:{summary:{vi:"Chuyên viên sản xuất video và hậu kỳ biến kịch bản thành sản phẩm hoàn chỉnh: lập kế hoạch quay, quản lý dữ liệu, dựng, chỉnh màu, xử lý âm thanh, đồ họa và xuất file đúng đặc tả từng kênh phát. Nghề tạo ra nội dung hình ảnh thuyết phục và chuẩn kỹ thuật, đòi hỏi cảm quan kể chuyện, thành thạo phần mềm, hiểu chuẩn phát sóng và tôn trọng bản quyền.",en:"A video producer and post-production editor turns a script into a finished piece: shoot planning, media management, editing, colour grading, audio, graphics and exports that meet each outlet's spec. The role delivers persuasive, technically sound content and requires storytelling sense, software mastery, knowledge of broadcast standards and respect for copyright."},responsibilities:{vi:["Phân tích kịch bản, lập danh sách cảnh quay, lịch quay và dự toán sản xuất.","Sao lưu, đặt tên và quản lý dữ liệu quay theo quy trình để không mất cảnh.","Dựng phim, chỉnh màu, làm đồ họa chuyển động và phụ đề theo định hướng đã duyệt.","Mix âm thanh, đo độ lớn và đỉnh thật theo đặc tả kênh phát.","Xuất nhiều định dạng, kiểm tra kỹ thuật (QC) và quản lý giấy phép nhạc, cảnh quay."],en:["Break down the script into a shot list, shooting schedule and production budget.","Back up, name and manage camera media so no footage is lost.","Edit, grade colour and build motion graphics and subtitles to the approved direction.","Mix audio and measure loudness and true peak to the outlet's spec.","Export multiple formats, run technical QC and manage music and footage licences."]},competencies:[{name:{vi:"Kể chuyện bằng hình ảnh",en:"Visual storytelling"},desc:{vi:"Chọn cảnh, nhịp dựng và âm thanh để truyền đúng thông điệp trong thời lượng giới hạn.",en:"Choose shots, pacing and sound to land the message within a tight duration."}},{name:{vi:"Kỹ thuật dựng & màu",en:"Editing & colour"},desc:{vi:"Làm chủ timeline, proxy, chỉnh màu sơ cấp, thứ cấp và quản lý không gian màu.",en:"Master timelines, proxies, primary and secondary grading and colour space management."}},{name:{vi:"Âm thanh hậu kỳ",en:"Audio post"},desc:{vi:"Làm sạch thoại, cân bằng nhạc, hiệu ứng và chuẩn hóa độ lớn theo LUFS.",en:"Clean dialogue, balance music and effects and normalise loudness in LUFS."}},{name:{vi:"Quản lý dữ liệu & quy trình",en:"Media management"},desc:{vi:"Sao lưu theo quy tắc 3-2-1, đặt tên nhất quán, theo dõi phiên bản và bàn giao gọn gàng.",en:"Follow the 3-2-1 backup rule, name consistently, track versions and deliver cleanly."}},{name:{vi:"Bản quyền & đạo đức",en:"Rights & ethics"},desc:{vi:"Kiểm tra giấy phép nhạc, cảnh quay, quyền hình ảnh cá nhân và không cắt ghép làm sai lệch sự thật.",en:"Check music, footage and likeness rights and never edit to distort the truth."}}],knowledge:{vi:["EBU R128: chuẩn hóa độ lớn -23 LUFS, đỉnh thật tối đa -1 dBTP cho phát sóng.","ITU-R BS.1770: thuật toán đo độ lớn (LUFS/LKFS) và đỉnh thật.","ITU-R BT.709 cho video HD và BT.2020 cho UHD: không gian màu và đặc tính truyền.","Tốc độ khung hình: 25/50 fps cho vùng điện 50 Hz, 23.976/29.97 fps cho vùng 60 Hz; quy đổi sai gây giật hình.","Luật Sở hữu trí tuệ số 50/2005/QH11 (đã sửa đổi, bổ sung): quyền tác giả, quyền liên quan với âm nhạc, bản ghi âm, tác phẩm điện ảnh.","Codec trung gian nén nội khung cho dựng và codec nén liên khung H.264, H.265 cho phát hành."],en:["EBU R128: loudness normalised to -23 LUFS with true peak no higher than -1 dBTP for broadcast.","ITU-R BS.1770: the algorithm for measuring loudness (LUFS/LKFS) and true peak.","ITU-R BT.709 for HD and BT.2020 for UHD: colour space and transfer characteristics.","Frame rates: 25/50 fps in 50 Hz regions, 23.976/29.97 fps in 60 Hz regions; wrong conversion causes judder.","Intellectual Property Law No. 50/2005/QH11 (as amended): copyright and related rights in music, sound recordings and films.","Intra-frame intermediate codecs for editing and inter-frame H.264 and H.265 codecs for distribution."]},tools:["Phần mềm dựng phim phi tuyến","Phần mềm chỉnh màu","Phần mềm âm thanh số và máy đo LUFS","Phần mềm đồ họa chuyển động","Màn hình tham chiếu đã hiệu chuẩn","Hệ thống lưu trữ RAID và sao lưu ngoài"],kpis:{vi:["Tỷ lệ file giao đạt QC kỹ thuật của kênh ngay lần đầu.","Tỷ lệ giao bản dựng, bản hoàn thiện đúng lịch duyệt.","Số vòng chỉnh sửa trung bình mỗi dự án.","Tỷ lệ nhạc, cảnh quay, font có giấy phép lưu hồ sơ (mục tiêu 100%)."],en:["Share of deliverables passing the channel's technical QC first time.","Share of rough cuts and masters delivered on the approved schedule.","Average revision rounds per project.","Share of music, footage and fonts with licences on file (target 100%)."]},day:[{time:"08:30",vi:"Kiểm tra bản sao lưu dữ liệu quay hôm qua ở hai nơi lưu trữ, tạo proxy.",en:"Verify yesterday's camera media backups in two locations and create proxies."},{time:"10:00",vi:"Dựng bản rough cut theo kịch bản phân cảnh, chọn nhạc thư viện có giấy phép.",en:"Cut the rough edit from the storyboard and pick licensed library music."},{time:"13:30",vi:"Chỉnh màu, làm đồ họa và phụ đề theo góp ý của khách.",en:"Grade colour and add graphics and subtitles from client notes."},{time:"15:30",vi:"Mix âm thanh, đo LUFS, đỉnh thật và chạy QC kỹ thuật.",en:"Mix audio, measure LUFS and true peak and run technical QC."},{time:"17:30",vi:"Xuất file theo đặc tả, gửi link duyệt và cập nhật nhật ký phiên bản.",en:"Export to spec, send the review link and update the version log."}],mistakes:{vi:["Đặt timeline sai tốc độ khung hình so với cảnh quay và đặc tả kênh, gây giật hình, lệch tiếng.","Chuẩn hóa âm thanh bằng preset mạng xã hội cho bản phát sóng, bị kênh trả file.","Dùng nhạc, cảnh quay lấy trên mạng không có giấy phép, khiến chiến dịch bị gỡ hoặc khiếu nại."],en:["Setting a timeline frame rate that differs from the footage and spec, causing judder and sync drift.","Normalising a broadcast master with a social media preset, so the channel rejects it.","Using music or footage from the web without a licence, getting the campaign taken down or claimed."]},career:[{vi:"Trợ lý dựng",en:"Assistant editor"},{vi:"Biên tập dựng phim",en:"Video editor"},{vi:"Biên tập dựng cấp cao, giám sát hậu kỳ",en:"Senior editor, post-production supervisor"},{vi:"Nhà sản xuất, trưởng bộ phận sản xuất",en:"Producer, head of production"}],glossary:[{term:"LUFS",vi:"Đơn vị đo độ lớn âm thanh cảm nhận theo ITU-R BS.1770, tính so với thang đầy đủ.",en:"Loudness Units relative to Full Scale, the perceived loudness unit defined in ITU-R BS.1770."},{term:"True peak",vi:"Mức đỉnh thật của tín hiệu sau tái tạo, đo bằng dBTP, dùng để tránh méo khi chuyển đổi.",en:"The reconstructed signal peak in dBTP, used to avoid clipping during conversion."},{term:"Frame rate",vi:"Số khung hình mỗi giây của video, ví dụ 25, 29.97 hoặc 50 fps.",en:"The number of video frames per second, such as 25, 29.97 or 50 fps."},{term:"Proxy",vi:"Bản sao độ phân giải thấp của cảnh quay để dựng nhanh, liên kết lại bản gốc khi xuất.",en:"A low-resolution copy of footage for fast editing, relinked to the originals at export."},{term:"QC",vi:"Kiểm tra chất lượng kỹ thuật hình, tiếng, định dạng trước khi giao file.",en:"Technical quality control of picture, sound and format before delivery."}],quiz:[{q:{vi:"Bản mix đo được -16 LUFS, kênh yêu cầu -23 LUFS. Cần áp mức hiệu chỉnh nào?",en:"A mix measures -16 LUFS and the channel requires -23 LUFS. What gain should you apply?"},options:{vi:["+7 dB","-7 dB","-23 dB","+16 dB"],en:["+7 dB","-7 dB","-23 dB","+16 dB"]},answer:1,explain:{vi:"-23 - (-16) = -7 dB; cần giảm 7 dB rồi đo lại đỉnh thật.",en:"-23 - (-16) = -7 dB; reduce by 7 dB, then re-check true peak."}},{q:{vi:"Theo EBU R128, mức đỉnh thật tối đa thường áp dụng cho phát sóng là bao nhiêu?",en:"Under EBU R128, what is the usual maximum true peak for broadcast?"},options:{vi:["0 dBTP","-6 dBTP","+1 dBTP","-1 dBTP"],en:["0 dBTP","-6 dBTP","+1 dBTP","-1 dBTP"]},answer:3,explain:{vi:"EBU R128 đặt đỉnh thật tối đa -1 dBTP để còn khoảng an toàn khi mã hóa.",en:"EBU R128 sets a -1 dBTP maximum true peak to leave headroom for encoding."}},{q:{vi:"Khách muốn dùng một bài hát nổi tiếng chưa có giấy phép cho TVC. Bạn làm gì?",en:"The client wants a famous song with no licence in the TV spot. What do you do?"},options:{vi:["Từ chối, đề xuất nhạc có giấy phép và báo Producer","Chỉ dùng 15 giây là không sao","Đổi tốc độ bài hát để tránh bị phát hiện","Dùng rồi ghi tên ca sĩ là đủ"],en:["Refuse, propose licensed music and inform the producer","Using only 15 seconds is fine","Change the tempo to avoid detection","Use it and credit the singer"]},answer:0,explain:{vi:"Mọi đoạn nhạc dùng cho quảng cáo đều cần giấy phép; ghi tên hay cắt ngắn không thay được giấy phép.",en:"Any music used in advertising needs a licence; credits or short clips do not replace it."}},{q:{vi:"Cảnh quay 25 fps, kênh vùng 50 Hz yêu cầu 25 fps. Cách làm đúng là gì?",en:"Footage is 25 fps and a 50 Hz channel requires 25 fps. What is correct?"},options:{vi:["Đặt timeline 29.97 fps","Đặt 23.976 fps cho chất điện ảnh","Đặt timeline và xuất ở 25 fps","Đặt 60 fps cho mượt"],en:["Use a 29.97 fps timeline","Use 23.976 fps for a film look","Edit and export at 25 fps","Use 60 fps for smoothness"]},answer:2,explain:{vi:"Giữ tốc độ khung hình gốc và đúng đặc tả kênh tránh giật hình, lệch tiếng và bị trả file.",en:"Keeping the native rate that matches the spec avoids judder, sync drift and rejection."}}],tools_en:["Non-linear editing software (NLE)","Color grading software","Digital audio workstation and LUFS meter","Motion graphics software","Calibrated reference monitor","RAID storage and external backup"]}}})})(window.KKR);
